import sys, json, re, hashlib, base64, datetime, difflib, fnmatch

# THE READING SIDE OF A FILE SPACE (file-space, GH #899). Every read of a file
# in this space arrives here on `in_read` and leaves as exactly one `answer`:
# `info`, `read`, `search` (exact, regex), `summary`, `history`, `show`,
# `diff`, `list`, `find`, `raw`. `ask` and the semantic search go to
# `./derive`; this cell never sees them.
#
# A FILE IS AN ADDRESS, NOT A PLACE (ADR 0047). A request names a file by its
# id (`fh-<12 hex>`) or its path, optionally pinned to a version (`@<hex>`),
# a workspace (`@ws:<name>`) or a snapshot (`@snap:<name>`). No answer field
# carries where the file lives: not the store, not the space, not the hive.
# Moving every row of a file into another space's store changes no answer.
#
# EVERY QUERY NAMES ITS FILE. The one store holds the rows of every file of
# the space; a row belongs to the file its `file` column names, and a block
# hash shared by two files is two rows. So every select on a table with a
# `file` column carries `file` in its `where` -- the only exception is
# `files` itself, for the path lookup, `list` and `find` -- and every select
# carries a `limit` (a select without one is unbounded).
#
# THIS CELL NEVER WRITES A FILE. The one table it writes is `pending`, its own
# working values between two store phases (`op`, `op_id`, `caller`, `ws` and
# the arguments do not survive a hop, and a working value never rides in
# context). A prepared commit is read as it stands -- committed: the plan's
# target, else the head -- and never recovered from here.
#
# The request: body `{op, file?, args{}}`, hop `op`, `op_id`, `ws?`, `mode?`,
# `caller?`. The answer: route `answer`, hop `op`, `op_id`, `caller` mirrored,
# body `{ok, op, op_id, file, version, ...}` or `{ok: false, op, op_id,
# error: {code, message}}`.
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}


def _int(key, default):
    v = P.get(key, default)
    if v is None or (isinstance(v, str) and not v.strip()):
        return default
    return int(float(v))


MAX_LINES = max(1, _int("max_lines", 2000))
MAX_CHARS = max(100, _int("max_chars", 25000))
SEARCH_LIMIT = max(1, _int("search_limit", 20))
DIFF_LINES = max(10, _int("diff_lines", 400))

ME = "read"
FMT = "%Y-%m-%dT%H:%M:%S.%fZ"
OPS = ("info", "read", "search", "summary", "history", "show", "diff", "list", "find", "raw")
# Ops that address no single file.
SPACE_OPS = ("list", "find")
# Ops whose answer needs the content of a version.
CONTENT_OPS = ("read", "search", "show", "diff", "raw")
PATTERN_MAX = 500
LONG_LINE = 4000
CONTEXT_MAX = 2
SHOW_LINES = 40
HISTORY_MAX = 200
BLOCK_TRANCHE = 200
PARTS_MAX = 5000
CANDIDATES_MAX = 10
LIST_SCAN = 2000
FIND_PAGE = 500
FIND_SCAN = 20000
FIND_LIMIT = 100
FIND_LIMIT_MAX = 500
ID_RE = re.compile(r"^fh-[0-9a-f]{12}$")
HEX_RE = re.compile(r"^[0-9a-f]{4,64}$")
NAME_RE = re.compile(r"^[A-Za-z0-9._-]{1,64}$")


# ============================================================ THE TWINS
# `parse_addr`, `line_hash` and `text_view` recur word for word in every cell
# of this space that needs them (`script_inline` has no library); the lock
# `gh899_the_twins_parse_one_address` runs every copy against one table.

def parse_addr(s):
    """An address -> {file, path, at, ref, anchor}; `at` is `head`, `v`
    (`ref` a hex prefix), `ws` or `snap` (`ref` a name). A malformed address
    is {error: 'bad_address'}. An anchor (`#...`) is parsed, never resolved."""
    if not isinstance(s, str) or not s.strip() or len(s) > 1024:
        return {"error": "bad_address"}
    s = s.strip()
    anchor = ""
    if "#" in s:
        s, anchor = s.split("#", 1)
        if not anchor:
            return {"error": "bad_address"}
    at, ref = "head", ""
    if "@" in s:
        base, suffix = s.rsplit("@", 1)
        if suffix.startswith("ws:") or suffix.startswith("snap:"):
            kind, name = suffix.split(":", 1)
            if not NAME_RE.match(name):
                return {"error": "bad_address"}
            at, ref, s = kind, name, base
        elif HEX_RE.match(suffix):
            at, ref, s = "v", suffix, base
        elif ID_RE.match(base):
            return {"error": "bad_address"}
    if ID_RE.match(s):
        return {"file": s, "path": "", "at": at, "ref": ref, "anchor": anchor}
    if s.startswith("/") and "\x00" not in s and "//" not in s and len(s) > 1 \
            and not s.endswith("/"):
        return {"file": "", "path": s, "at": at, "ref": ref, "anchor": anchor}
    return {"error": "bad_address"}


def line_hash(line):
    """`h4`: the first four hex digits of the sha256 of one line without its
    line ending (`\\n`, `\\r\\n`)."""
    if line.endswith("\n"):
        line = line[:-1]
    if line.endswith("\r"):
        line = line[:-1]
    return hashlib.sha256(line.encode("utf-8")).hexdigest()[:4]


def text_view(content, derived):
    """The text a version reads as: its derived pages (`[{part, text}]`),
    each headed `--- page <n> ---`, when it has any, else its own lines when
    the content is UTF-8 without NUL. Pages first: an extractor made them
    because the bytes are not the text, and a PDF can be pure ASCII
    (GH #907, OR-FJ.I.22). {kind, lines, pages: {n: [from, to]}} (1-based,
    inclusive) or {error: 'no_text'}. A line keeps a `\\r` of its ending;
    `\\n` ends a line, a last line without one counts."""
    def split(t):
        if t == "":
            return []
        parts = t.split("\n")
        if t.endswith("\n"):
            parts = parts[:-1]
        return parts

    parts = sorted((p for p in (derived or []) if isinstance(p, dict)),
                   key=lambda p: int(p.get("part") or 0))
    text = None
    if not parts and isinstance(content, (bytes, bytearray)) and b"\x00" not in content:
        try:
            text = bytes(content).decode("utf-8")
        except UnicodeDecodeError:
            text = None
    if text is not None:
        return {"kind": "text", "lines": split(text), "pages": {}}
    if not parts:
        return {"error": "no_text"}
    lines, pages = [], {}
    for p in parts:
        n = int(p.get("part") or 0)
        start = len(lines) + 1
        lines.append("--- page %d ---" % n)
        lines.extend(split(str(p.get("text") or "")))
        pages[n] = [start, len(lines)]
    return {"kind": "derived", "lines": lines, "pages": pages}


# ============================================================ PLUMBING

def emit(msgs):
    # OR-FJ.L.8: a body with none of `messages`/`system`/`attachments` is no
    # UBF body, and a debug colony dead-letters it without an answer
    # (`invalid_ubf_body`) -- measured in the gh908 colony lock on the
    # `in_check` of `write`. Every emission leaves with its slot.
    for m in msgs:
        if isinstance(m, dict) and not any(k in m for k in ("messages", "system", "attachments")):
            m["messages"] = []
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def park(reason=""):
    if reason:
        sys.stderr.write("file-space/read: %s\n" % reason)
    emit([])


def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime(FMT)


def v12(v):
    return str(v or "")[:12]


def loads(v, default):
    if isinstance(v, str):
        try:
            return json.loads(v)
        except Exception:
            return default
    return default if v is None else v


def sel(table, columns, where, order=None, limit=1):
    a = {"operation": "select", "table": table, "columns": columns, "where": where,
         "limit": int(limit)}
    if order:
        a["order_by"] = [{"col": c, "dir": o} for c, o in order]
    return a


def store(ops, phase):
    return {"header": {"route": "read_store", "phase": phase, "reply_cell": ME},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def legs(body):
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": ""}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": ""})
                leg["error_code"] = str(r.get("error_code") or "")
    elif len(out) == 1:
        next(iter(out.values()))["error_code"] = str(hop.get("error_code") or "")
    return out


def rows(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return p if isinstance(p, list) else []


def one(lg, cid):
    r = rows(lg, cid)
    return r[0] if r else None


def parked_ops(S, phase, first=False):
    """The two legs every non-final bundle opens with: park the working values
    (insert on the first phase, update after), then echo them back."""
    key = {"op_id": S["op_id"], "cell": ME}
    body = json.dumps(S, sort_keys=True)
    if first:
        put = {"operation": "insert", "table": "pending",
               "row": {"op_id": S["op_id"], "cell": ME, "phase": phase, "body": body,
                       "at": now()}}
    else:
        put = {"operation": "update", "table": "pending",
               "set": {"phase": phase, "body": body}, "where": key}
    return [("p-put", put),
            ("p-echo", sel("pending", ["op_id", "body"], key, None, 1))]


def next_phase(S, phase, ops, first=False):
    emit([store(parked_ops(S, phase, first) + ops, phase)])


def finish(S, body, parked=True):
    msg = {"header": {"route": "answer", "op": S["op"], "op_id": S["op_id"],
                      "caller": S.get("caller", "")},
           "messages": [], "op": S["op"], "op_id": S["op_id"]}
    msg.update(body)
    msgs = [msg]
    if parked:
        msgs.append(store([("p-drop", {"operation": "delete", "table": "pending",
                                       "where": {"op_id": S["op_id"], "cell": ME}})],
                          "done"))
    emit(msgs)


def fail(S, code, message, parked=True, extra=None):
    err = {"code": code, "message": message}
    err.update(extra or {})
    finish(S, {"ok": False, "error": err}, parked)


def ok(S, body):
    out = {"ok": True}
    if S.get("file_id"):
        out["file"] = S["file_id"]
    out.update(body)
    finish(S, out)


# ============================================================ PURE READS

def fmt_line(n, line):
    if line.endswith("\r"):
        line = line[:-1]
    return "%d:%s|%s" % (n, line_hash(line), line)


def window(lines, a, b):
    """Lines a..b (1-based, inclusive) formatted, cut at MAX_LINES and
    MAX_CHARS; -> (text, first, last, more)."""
    total = len(lines)
    out, chars, last = [], 0, a - 1
    for n in range(a, b + 1):
        s = fmt_line(n, lines[n - 1])
        if len(out) >= MAX_LINES or (out and chars + len(s) + 1 > MAX_CHARS):
            break
        out.append(s)
        chars += len(s) + 1
        last = n
    more = None
    if last < b:
        nxt = last + 1
        more = {"from": nxt, "to": min(b, nxt + MAX_LINES - 1)}
    return "\n".join(out), a, last, more


def span(args, total):
    """`from`/`to` 1-based inclusive, negative counts from the end."""
    def num(k, dflt):
        v = args.get(k)
        if v is None or v == "":
            return dflt
        return int(v)
    a = num("from", 1)
    b = num("to", 0)
    if a < 0:
        a = total + 1 + a
    if b < 0:
        b = total + 1 + b
    if b == 0:
        # No end given: to the end of the file; `window` stops at the limits
        # and `more` names the rest.
        b = total
    a = max(1, a)
    b = min(total, b)
    return a, b


def ctx_line(n, raw):
    """A context line in read form, its text cut at LONG_LINE (the hash is
    of the whole line)."""
    t = raw[:-1] if raw.endswith("\r") else raw
    return "%d:%s|%s" % (n, line_hash(t), t[:LONG_LINE])


def search_lines(lines, pattern, mode, context, limit):
    """-> (hits, total, cut): at most `limit` hits, and no more than
    MAX_CHARS of text across them (`cut` then says so)."""
    if mode == "regex":
        rx = re.compile(pattern)
        match = lambda t: rx.search(t) is not None
    else:
        match = lambda t: pattern in t
    hits, total, chars, cut = [], 0, 0, False
    for i, raw in enumerate(lines):
        t = raw[:-1] if raw.endswith("\r") else raw
        long_line = len(t) > LONG_LINE
        probe = t[:LONG_LINE] if long_line else t
        if not match(probe):
            continue
        total += 1
        if len(hits) >= limit or cut:
            continue
        n = i + 1
        hit = {"line": n, "h4": line_hash(t), "text": probe}
        if long_line:
            hit["long_line"] = True
        if context:
            hit["before"] = [ctx_line(k, lines[k - 1]) for k in range(max(1, n - context), n)]
            hit["after"] = [ctx_line(k, lines[k - 1])
                            for k in range(n + 1, min(len(lines), n + context) + 1)]
        size = len(hit["text"]) + sum(len(x) + 1 for x in hit.get("before", []) + hit.get("after", []))
        if hits and chars + size > MAX_CHARS:
            cut = True
            continue
        chars += size
        hits.append(hit)
    return hits, total, cut


def unified(a_lines, b_lines, a_name, b_name):
    a = [x + "\n" for x in a_lines]
    b = [x + "\n" for x in b_lines]
    out = [x.rstrip("\n") for x in difflib.unified_diff(a, b, a_name, b_name, n=3)]
    cut = len(out) > DIFF_LINES
    out = out[:DIFF_LINES]
    chars = 0
    for i, x in enumerate(out):
        chars += len(x) + 1
        if i and chars > MAX_CHARS:
            out, cut = out[:i], True
            break
    return "\n".join(out), cut


def history_rows(rows_, limit):
    """`line` rows newest first, a commit's line once -- its smallest `seq`:
    a recovery race can append the same commit twice (OR-FH-85)."""
    last = {}
    for i, r in enumerate(rows_):
        c = str(r.get("commit") or "")
        if c:
            last[c] = i
    out = [r for i, r in enumerate(rows_)
           if not str(r.get("commit") or "") or last[str(r.get("commit"))] == i]
    return out[:limit]


def assemble(version_row, blocks_rows):
    """The bytes of a version from its block list; None when a block is
    missing (corrupt -- never skipped)."""
    hashes = loads(version_row.get("blocks"), [])
    have = {}
    for r in blocks_rows:
        have[str(r.get("hash") or "")] = r
    parts = []
    for h in hashes:
        r = have.get(str(h))
        if r is None:
            return None
        body = str(r.get("body") or "")
        if str(r.get("enc") or "utf8") == "b64":
            try:
                parts.append(base64.b64decode(body, validate=True))
            except Exception:
                return None
        else:
            parts.append(body.encode("utf-8"))
    return b"".join(parts)


def list_entries(rows_, prefix, depth):
    """Files under `prefix` (rows ordered by path) grouped to `depth`
    segments: a file within reach is itself, a deeper one counts toward its
    directory at the cut."""
    base = prefix if prefix.endswith("/") else prefix + "/"
    files, dirs = [], {}
    for r in rows_:
        path = str(r.get("path") or "")
        if path == prefix:
            files.append(r)
            continue
        if not path.startswith(base):
            continue
        segs = path[len(base):].split("/")
        if len(segs) <= depth:
            files.append(r)
        else:
            d = base + "/".join(segs[:depth]) + "/"
            dirs[d] = dirs.get(d, 0) + 1
    out = [{"path": str(r.get("path")), "file": str(r.get("file")),
            "bytes": int(r.get("bytes") or 0), "lines": int(r.get("lines") or 0)}
           for r in files]
    out += [{"path": k, "dir": True, "files": v} for k, v in dirs.items()]
    out.sort(key=lambda e: e["path"])
    return out


# ============================================================ PHASES

def files_cols():
    return ["file", "path", "kind", "mime", "head", "head_seq", "lock", "tomb",
            "oneline", "bytes", "lines", "born_at"]


def prefix_lookup(cid, file_id, pfx):
    return (cid, sel("versions", ["version"],
                     {"file": file_id, "version": {"gte": pfx}} if len(pfx) < 64
                     else {"file": file_id, "version": pfx},
                     [("version", "asc")], CANDIDATES_MAX))


def pick(lg, cid, pfx):
    """A hex prefix within one file -> (full, error, candidates)."""
    got = [str(r.get("version") or "") for r in rows(lg, cid)]
    got = [v for v in got if v.startswith(pfx)]
    if not got:
        return "", "version_unknown", []
    if len(got) > 1:
        return "", "version_ambiguous", [v12(v) for v in got]
    return got[0], "", []


def start(S):
    op = S["op"]
    if op in SPACE_OPS:
        args = S["args"]
        if op == "list":
            prefix = str(args.get("prefix") or "/")
            if not prefix.startswith("/"):
                fail(S, "bad_request", "a prefix starts with /", parked=False)
            depth = int(args.get("depth") or 1)
            if depth < 1:
                fail(S, "bad_request", "depth is at least 1", parked=False)
            # No `like` and one operator per column: the range starts at the
            # prefix, and the rows past it are cut off here.
            where = {"path": {"gte": prefix}, "tomb": "", "head": {"neq": ""}}
            S["list"] = {"prefix": prefix, "depth": depth}
            next_phase(S, "list", [("l-files", sel(
                "files", ["file", "path", "bytes", "lines"], where, [("path", "asc")],
                LIST_SCAN + 1))], first=True)
        glob = str(args.get("glob") or "")
        if not glob or len(glob) > PATTERN_MAX:
            fail(S, "bad_request", "find takes a glob", parked=False)
        limit = min(FIND_LIMIT_MAX, max(1, int(args.get("limit") or FIND_LIMIT)))
        S["find"] = {"glob": glob, "limit": limit, "after": "", "scanned": 0, "hits": []}
        next_phase(S, "find", [find_page(S)], first=True)
    addr = S["addr"]
    ops = []
    if addr["file"]:
        ops.append(("f-row", sel("files", files_cols(), {"file": addr["file"]}, None, 1)))
    else:
        ops.append(("f-row", sel("files", files_cols(), {"path": addr["path"], "tomb": ""},
                                 [("born_at", "asc")], 2)))
    if S.get("ws_name"):
        ops.append(("w-row", sel("ws", ["ws", "name", "root", "base_seq", "state"],
                                 {"name": S["ws_name"], "state": "open"},
                                 [("opened_at", "desc")], 1)))
    next_phase(S, "file", ops, first=True)


def find_page(S):
    f = S["find"]
    where = {"tomb": "", "head": {"neq": ""}}
    if f["after"]:
        where["path"] = {"gt": f["after"]}
    return ("f-page", sel("files", ["file", "path"], where, [("path", "asc")], FIND_PAGE))


def on_find(S, lg):
    f = S["find"]
    page = rows(lg, "f-page")
    for r in page:
        path = str(r.get("path") or "")
        if fnmatch.fnmatchcase(path, f["glob"]) and len(f["hits"]) < f["limit"] + 1:
            f["hits"].append({"file": str(r.get("file")), "path": path})
    f["scanned"] += len(page)
    if page:
        f["after"] = str(page[-1].get("path") or "")
    done = len(page) < FIND_PAGE or len(f["hits"]) > f["limit"] or f["scanned"] >= FIND_SCAN
    if not done:
        next_phase(S, "find", [find_page(S)])
    more = len(f["hits"]) > f["limit"] or (len(page) == FIND_PAGE and f["scanned"] >= FIND_SCAN)
    body = {"glob": f["glob"], "files": f["hits"][:f["limit"]]}
    if more:
        body["more"] = True
    ok(S, body)


def on_list(S, lg):
    L = S["list"]
    got = rows(lg, "l-files")
    cut = len(got) > LIST_SCAN and str(got[LIST_SCAN].get("path") or "").startswith(L["prefix"])
    got = [r for r in got[:LIST_SCAN] if str(r.get("path") or "").startswith(L["prefix"])]
    body = {"prefix": L["prefix"], "depth": L["depth"],
            "entries": list_entries(got, L["prefix"], L["depth"])}
    if cut:
        body["more"] = True
    ok(S, body)


def extras(S):
    """The version prefixes an op names besides its address."""
    a = S["args"]
    out = {}
    if S["op"] in ("show", "raw") and a.get("version"):
        out["x-version"] = str(a.get("version"))
    if S["op"] == "diff":
        if a.get("a"):
            out["x-a"] = str(a.get("a"))
        if a.get("b"):
            out["x-b"] = str(a.get("b"))
    return out


def on_file(S, lg):
    addr = S["addr"]
    got = rows(lg, "f-row")
    if not got:
        fail(S, "not_found", "no such file")
    if len(got) > 1:
        # Two live files under one path break the space's own rule; the older
        # birth is the one the path names.
        sys.stderr.write("file-space/read: two live files under one path\n")
    F = got[0]
    S["file_id"] = str(F.get("file") or "")
    S["frow"] = {k: F.get(k) for k in files_cols()}
    at = addr["at"]
    ws_name = S.get("ws_name") or ""
    if at == "head" and ws_name:
        at = "ws"
    if ws_name:
        W = one(lg, "w-row")
        if W is None:
            fail(S, "ws_unknown", "no open workspace of that name")
        S["wrow"] = W
    if at == "head" and str(F.get("tomb") or "") and S["op"] != "info":
        fail(S, "tombstoned", "the file was removed; its versions stay readable by version")
    # Born in a workspace (`head` ''): no file outside it, by head, version or
    # snapshot (review S M-4) -- unless a commit holds its lock: then the
    # commit decides, all or nothing (review S I-1, section 2.7).
    if (at != "ws" and not ws_name and not str(F.get("head") or "")
            and not str(F.get("lock") or "")):
        fail(S, "not_found", "no such file")
    for k, pfx in extras(S).items():
        if not HEX_RE.match(pfx):
            fail(S, "bad_request", "a version is 4 to 64 hex digits")
    if S["op"] == "diff" and not S["args"].get("a"):
        fail(S, "bad_request", "diff takes a (and b, else the addressed state)")
    fid = S["file_id"]
    ops = []
    if at == "v":
        ops.append(prefix_lookup("v-main", fid, addr["ref"]))
    elif at == "snap":
        ops.append(("s-row", sel("snaps", ["name", "version"], {"file": fid, "name": addr["ref"]},
                                 [("at", "desc")], 1)))
    elif at == "ws":
        W = S["wrow"]
        ops.append(("w-file", sel("ws_files", ["base", "working", "state"],
                                  {"file": fid, "ws": str(W.get("ws") or "")}, [("at", "desc")], 1)))
        ops.append(("w-line", sel("line", ["seq", "version"],
                                  {"file": fid, "seq": {"lte": int(W.get("base_seq") or 0)}},
                                  [("seq", "desc")], 1)))
    elif str(F.get("lock") or ""):
        ops.append(("c-row", sel("commits", ["commit", "state", "plan"],
                                 {"commit": str(F.get("lock"))}, None, 1)))
    for k, pfx in extras(S).items():
        ops.append(prefix_lookup(k, fid, pfx))
    S["at"] = at
    if not ops:
        S["V"] = str(F.get("head") or "")
        to_meta(S, first=False)
    next_phase(S, "version", ops)


def on_version(S, lg):
    at = S["at"]
    F = S["frow"]
    if at == "v":
        V, err, cands = pick(lg, "v-main", S["addr"]["ref"])
        if err:
            fail(S, err, "no single version of this file starts with that prefix",
                 extra={"candidates": cands} if cands else None)
    elif at == "snap":
        r = one(lg, "s-row")
        if r is None:
            fail(S, "snap_unknown", "no snapshot of that name")
        V = str(r.get("version") or "")
    elif at == "ws":
        wf = one(lg, "w-file")
        if wf is not None:
            if str(wf.get("state") or "") == "removed":
                fail(S, "not_found", "the file is removed in this workspace")
            V = str(wf.get("working") or "")
        else:
            ln = one(lg, "w-line")
            if ln is None:
                fail(S, "not_found", "the file did not exist when the workspace opened")
            V = str(ln.get("version") or "")
    else:
        V = str(F.get("head") or "")
        c = one(lg, "c-row")
        if c is not None and str(c.get("state") or "") == "committed":
            # Past the commit point the plan's target is the file, also when
            # it is '' (a committed remove) or the head is '' (born in the
            # workspace) -- the other files of the commit already show it.
            for step in loads(c.get("plan"), []) or []:
                if isinstance(step, dict) and step.get("file") == S["file_id"]:
                    V = str(step.get("to") or "")
        if not V:
            fail(S, "not_found", "no such file")
    S["V"] = V
    xs = {}
    for k, pfx in extras(S).items():
        full, err, cands = pick(lg, k, pfx)
        if err:
            fail(S, err, "no single version of this file starts with %s" % pfx,
                 extra={"candidates": cands} if cands else None)
        xs[k] = full
    S["x"] = xs
    to_meta(S)


def wanted(S):
    """The full versions whose rows the op reads."""
    x = S.get("x") or {}
    op = S["op"]
    if op in ("show", "raw"):
        return [x.get("x-version") or S["V"]]
    if op == "diff":
        return [x.get("x-a") or S["V"], x.get("x-b") or S["V"]]
    return [S["V"]]


def to_meta(S, first=False):
    fid, V, op, a = S["file_id"], S["V"], S["op"], S["args"]
    vs = sorted(set(wanted(S)))
    ops = [("m-ver", sel("versions", ["version", "blocks", "bytes", "lines", "parent", "force",
                                      "made_by", "at"],
                         {"file": fid, "version": {"in": vs}}, None, len(vs)))]
    if op == "info":
        ops.append(("m-parts", sel("derived", ["part"], {"file": fid, "version": V, "kind": "text"},
                                   None, PARTS_MAX)))
        ops.append(("m-wsf", sel("ws_files", ["ws", "state"], {"file": fid}, [("at", "desc")], 200)))
        ops.append(("m-ws", sel("ws", ["ws", "name"], {"state": "open"}, [("name", "asc")], 500)))
        ops.append(("m-snaps", sel("snaps", ["name", "version"], {"file": fid},
                                   [("name", "asc")], 200)))
    elif op == "summary":
        level = str(a.get("level") or "oneline")
        if level not in ("oneline", "short"):
            fail(S, "bad_request", "level is oneline or short")
        ops.append(("m-sum", sel("summaries", ["text", "model", "at"],
                                 {"file": fid, "version": V, "level": level},
                                 [("at", "desc")], 1)))
    elif op == "history":
        limit = min(HISTORY_MAX, max(1, int(a.get("limit") or 20)))
        ops.append(("m-line", sel("line", ["seq", "version", "prev", "op", "note", "ws", "commit", "at"],
                                  {"file": fid}, [("seq", "desc")], 2 * limit)))
        S["hist_limit"] = limit
    next_phase(S, "meta", ops, first=first)


def on_meta(S, lg):
    op, V = S["op"], S["V"]
    vrows = {str(r.get("version")): r for r in rows(lg, "m-ver")}
    for v in wanted(S):
        if v not in vrows:
            fail(S, "corrupt", "a version the file names is missing")
    VR = vrows[V] if V in vrows else vrows[wanted(S)[0]]
    F = S["frow"]
    if op == "info":
        opened = {str(r.get("ws")): str(r.get("name")) for r in rows(lg, "m-ws")}
        wss = sorted({opened[str(r.get("ws"))] for r in rows(lg, "m-wsf")
                      if str(r.get("ws")) in opened})
        body = {"version": v12(V), "path": str(F.get("path") or ""),
                "kind": str(F.get("kind") or ""), "mime": str(F.get("mime") or ""),
                "bytes": int(VR.get("bytes") or 0), "lines": int(VR.get("lines") or 0),
                "pages": len({int(r.get("part") or 0) for r in rows(lg, "m-parts")}),
                "oneline": str(F.get("oneline") or ""),
                "workspaces": wss,
                "snapshots": [{"name": str(r.get("name")), "version": v12(r.get("version"))}
                              for r in rows(lg, "m-snaps")]}
        if str(F.get("tomb") or ""):
            body["tomb"] = str(F.get("tomb"))
        ok(S, body)
    if op == "summary":
        r = one(lg, "m-sum")
        if r is None:
            ok(S, {"version": v12(V), "level": str(S["args"].get("level") or "oneline"),
                   "pending": True})
        ok(S, {"version": v12(V), "level": str(S["args"].get("level") or "oneline"),
               "text": str(r.get("text") or ""), "model": str(r.get("model") or ""),
               "at": str(r.get("at") or "")})
    if op == "history":
        entries = []
        for r in history_rows(rows(lg, "m-line"), int(S.get("hist_limit") or 20)):
            e = {"at": str(r.get("at") or ""), "version": v12(r.get("version")),
                 "op": str(r.get("op") or "")}
            for k in ("prev", "note", "ws", "commit"):
                val = str(r.get(k) or "")
                if val:
                    e[k] = v12(val) if k == "prev" else val
            entries.append(e)
        ok(S, {"version": v12(V), "entries": entries})
    # Content: every block of every wanted version, of THIS file only.
    hashes = []
    for v in sorted(set(wanted(S))):
        for h in loads(vrows[v].get("blocks"), []) or []:
            if str(h) not in hashes:
                hashes.append(str(h))
    S["vrows"] = {v: {"blocks": vrows[v].get("blocks"), "bytes": vrows[v].get("bytes"),
                      "lines": vrows[v].get("lines"), "parent": vrows[v].get("parent"),
                      "force": vrows[v].get("force"), "made_by": vrows[v].get("made_by"),
                      "at": vrows[v].get("at")}
                  for v in set(wanted(S))}
    fid = S["file_id"]
    ops = []
    for i in range(0, len(hashes), BLOCK_TRANCHE):
        chunk = hashes[i:i + BLOCK_TRANCHE]
        ops.append(("b-%d" % (i // BLOCK_TRANCHE), sel(
            "blocks", ["hash", "enc", "body"], {"file": fid, "hash": {"in": chunk}},
            None, len(chunk))))
    if op != "raw":
        vs = sorted(set(wanted(S)))
        ops.append(("d-parts", sel("derived", ["version", "part", "body"],
                                   {"file": fid, "version": {"in": vs}, "kind": "text"},
                                   [("part", "asc")], PARTS_MAX)))
    next_phase(S, "blocks", ops)


def view_of(S, lg, v, blocks_rows):
    content = assemble(S["vrows"][v], blocks_rows)
    if content is None:
        fail(S, "corrupt", "a block of this version is missing")
    parts = [{"part": r.get("part"), "text": r.get("body")}
             for r in rows(lg, "d-parts") if str(r.get("version")) == v]
    return content, text_view(content, parts)


def on_blocks(S, lg):
    op, V, a = S["op"], S["V"], S["args"]
    blocks_rows = []
    for cid in sorted(lg):
        if cid.startswith("b-"):
            blocks_rows.extend(rows(lg, cid))
    if op == "raw":
        v = wanted(S)[0]
        content = assemble(S["vrows"][v], blocks_rows)
        if content is None:
            fail(S, "corrupt", "a block of this version is missing")
        ok(S, {"version": v12(v), "mime": str(S["frow"].get("mime") or ""),
               "bytes": len(content), "b64": base64.b64encode(content).decode("ascii")})
    if op == "diff":
        va, vb = wanted(S)
        _, ta = view_of(S, lg, va, blocks_rows)
        _, tb = view_of(S, lg, vb, blocks_rows)
        if "error" in ta or "error" in tb:
            fail(S, "no_text", "this version has no text view")
        fid = S["file_id"]
        text, cut = unified(ta["lines"], tb["lines"], "%s@%s" % (fid, v12(va)),
                            "%s@%s" % (fid, v12(vb)))
        body = {"version": v12(V), "a": v12(va), "b": v12(vb), "diff": text}
        if cut:
            body["truncated"] = True
        ok(S, body)
    v = wanted(S)[0]
    _, tv = view_of(S, lg, v, blocks_rows)
    if "error" in tv:
        fail(S, "no_text", "this version has no text view")
    lines = tv["lines"]
    if op == "show":
        VR = S["vrows"][v]
        body = {"version": v12(v), "bytes": int(VR.get("bytes") or 0),
                "lines": int(VR.get("lines") or 0), "at": str(VR.get("at") or ""),
                "made_by": str(VR.get("made_by") or ""),
                "head": window(lines, 1, min(len(lines), SHOW_LINES))[0]}
        if str(VR.get("parent") or ""):
            body["parent"] = v12(VR.get("parent"))
        if str(VR.get("force") or "") not in ("", "0"):
            body["force"] = True
        ok(S, body)
    if op == "search":
        pattern = str(a.get("pattern") or "")
        mode = str(a.get("mode") or "exact")
        if not pattern or len(pattern) > PATTERN_MAX:
            fail(S, "bad_pattern", "a pattern is 1 to %d characters" % PATTERN_MAX)
        if mode not in ("exact", "regex"):
            fail(S, "bad_request", "mode is exact or regex here")
        if mode == "regex":
            try:
                re.compile(pattern)
            except re.error as e:
                fail(S, "bad_pattern", "not a regular expression: %s" % e)
        context = min(CONTEXT_MAX, max(0, int(a.get("context") or 0)))
        limit = min(SEARCH_LIMIT, max(1, int(a.get("limit") or SEARCH_LIMIT)))
        hits, total, cut = search_lines(lines, pattern, mode, context, limit)
        body = {"version": v12(V), "hits": hits, "total": total}
        if cut:
            body["more"] = True
        ok(S, body)
    # read
    total = len(lines)
    body = {"version": v12(V), "lines": total}
    if a.get("page") not in (None, ""):
        n = int(a.get("page"))
        if n not in tv["pages"]:
            fail(S, "page_unknown", "this version has no page %d" % n)
        pa, pb = tv["pages"][n]
        text, first, last, more = window(lines, pa, pb)
        body.update(page=n, pages=len(tv["pages"]))
    else:
        if total == 0:
            ok(S, dict(body, text=""))
        try:
            fa, fb = span(a, total)
        except (TypeError, ValueError):
            fail(S, "bad_request", "from and to are line numbers")
        if fa > fb:
            fail(S, "bad_range", "the range holds no line of %d" % total)
        text, first, last, more = window(lines, fa, fb)
    body.update({"from": first, "to": last, "text": text})
    if more:
        body["more"] = more
    ok(S, body)


# ============================================================ LANES
lane = str(hop.get("route") or "")
phase = str(ctx.get("cur_phase") or "")
op_ = str(hop.get("operation") or "")

if lane == "in_read":
    op = str(hop.get("op") or d.get("op") or "")
    S = {"op": op, "op_id": str(hop.get("op_id") or ""), "caller": str(hop.get("caller") or ""),
         "args": d.get("args") if isinstance(d.get("args"), dict) else {}}
    if not S["op_id"]:
        fail(S, "bad_request", "a request carries hop.op_id", parked=False)
    if op not in OPS:
        fail(S, "unknown_op", "this lane serves " + ", ".join(OPS), parked=False)
    ws_name = str(hop.get("ws") or "")
    if ws_name and not NAME_RE.match(ws_name):
        fail(S, "bad_request", "a workspace name is 1 to 64 of [A-Za-z0-9._-]", parked=False)
    if op not in SPACE_OPS:
        raw = d.get("file")
        at = S["args"].get("at")
        if at not in (None, "") and isinstance(raw, str) and "@" not in raw:
            raw = raw + "@" + str(at)
        addr = parse_addr(raw)
        if "error" in addr:
            fail(S, addr["error"], "an address is fh-<12 hex> or /path, with @<hex>, "
                 "@ws:<name> or @snap:<name>", parked=False)
        if addr["anchor"]:
            fail(S, "anchor_unsupported", "anchors are not served yet", parked=False)
        if addr["at"] == "ws":
            ws_name = addr["ref"]
        S["addr"] = addr
    S["ws_name"] = ws_name
    start(S)

if lane:
    park("unknown lane %r -- dropped" % lane)
if not op_:
    park("a message with neither a lane nor a store answer -- dropped")
if phase == "done":
    emit([])

lg = legs(d)
echo = one(lg, "p-echo")
parked = loads((echo or {}).get("body"), None)
if not isinstance(parked, dict):
    park("store answer in phase %r without its parked request -- dropped" % phase)
bad = sorted(cid for cid, leg in lg.items() if leg["error_code"])
if bad:
    sys.stderr.write("file-space/read: store refused %s in phase %s\n" % (", ".join(bad), phase))
    fail(parked, "store_error", "the store refused a read; try again later")

if phase == "file":
    on_file(parked, lg)
if phase == "version":
    on_version(parked, lg)
if phase == "meta":
    on_meta(parked, lg)
if phase == "blocks":
    on_blocks(parked, lg)
if phase == "list":
    on_list(parked, lg)
if phase == "find":
    on_find(parked, lg)
park("unknown phase %r -- dropped" % phase)
